package com.badrulamin.University_Management.entity;  import com.fasterxml.jackson.annotation.JsonProperty; import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.CreationTimestamp; import org.hibernate.annotations.UpdateTimestamp;  import java.time.LocalDateTime;  @Entity @Table(name = "admission_merit_list_entry") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class AdmissionMeritListEntry {      @Id     @GeneratedValue(strategy = GenerationType.IDENTITY)     private Long id;      @ManyToOne(fetch = FetchType.EAGER)     @JoinColumn(name = "merit_list_id", nullable = false)     private AdmissionMeritList meritList;      @ManyToOne(fetch = FetchType.EAGER)     @JoinColumn(name = "application_id", nullable = false)     private AdmissionApplication application;      @Column(name = "rank_no", nullable = false)     private Integer rank;      private Double score;      private Double testScore;      private Double academicScore;      private Double interviewScore;      private Double totalWeightedScore;      @Column(length = 50)     private String status;      private Boolean isOffered;      private Boolean isEnrolled;      @Column(length = 500)     private String remarks;      @Column(updatable = false)     @CreationTimestamp     private LocalDateTime createdAt;      @UpdateTimestamp     private LocalDateTime updatedAt;      @JsonProperty("meritListId")     public Long getMeritListId() {         return meritList != null ? meritList.getId() : null;     }      @JsonProperty("meritListId")     public void setMeritListId(Long meritListId) {         if (meritListId != null) {             AdmissionMeritList m = new AdmissionMeritList();             m.setId(meritListId);             this.meritList = m;         }     }      @JsonProperty("applicationId")     public Long getApplicationId() {         return application != null ? application.getId() : null;     }      @JsonProperty("applicationId")     public void setApplicationId(Long applicationId) {         if (applicationId != null) {             AdmissionApplication a = new AdmissionApplication();             a.setId(applicationId);             this.application = a;         }     } }